const cJSON*obj(const cJSON*p,const char*n){auto*v=cJSON_GetObjectItemCaseSensitive(p,n);return cJSON_IsObject(v)?v:nullptr;}
bool keys(const cJSON*v,std::initializer_list<const char*>a){for(auto*f=v?v->child:nullptr;f;f=f->next){bool ok=false;for(auto*n:a)ok|=f->string&&strcmp(f->string,n)==0;if(!ok)return false;}return true;}
