if(auto*u=obj(f,"usb")){if(!keys(u,{"vid","pid","interface","serial"}))return ESP_ERR_INVALID_ARG;int64_t vid,pid,in;if(!num(u,"vid",1,65535,vid)||!num(u,"pid",1,65535,pid)||!num(u,"interface",0,255,in)||!optstr(u,"serial",b.fiscal.usb_serial,128))return ESP_ERR_INVALID_ARG;b.fiscal.usb_vid=vid;b.fiscal.usb_pid=pid;b.fiscal.usb_interface=in;}
