auto*m=obj(root.get(),"mqtt");if(!m||!keys(m,{"uri","client_id","command_topic","sync_topic","ack_topic","root_ca_ref","client_certificate_ref","client_key_ref"})||!str(m,"uri",b.mqtt.uri,512)||b.mqtt.uri.rfind("mqtts://",0)!=0||!str(m,"client_id",b.mqtt.client_id)||!str(m,"command_topic",b.mqtt.command_topic,512)||!str(m,"sync_topic",b.mqtt.sync_topic,512)||!str(m,"ack_topic",b.mqtt.ack_topic,512)||!str(m,"root_ca_ref",b.mqtt.root_ca_ref,64)||!str(m,"client_certificate_ref",b.mqtt.client_certificate_ref,64)||!str(m,"client_key_ref",b.mqtt.client_key_ref,64))return ESP_ERR_INVALID_ARG;
