esp_err_t ProvisionedBindingStore::load(CompositeBinding&b){if(!impl_->open)return ESP_ERR_INVALID_STATE;size_t z=0;esp_err_t e=nvs_get_blob(impl_->h,"active",nullptr,&z);if(e!=ESP_OK)return e;if(!z||z>max_binding)return ESP_ERR_INVALID_SIZE;std::vector<char>raw(z);if((e=nvs_get_blob(impl_->h,"active",raw.data(),&z))!=ESP_OK||(e=decode_and_validate(raw.data(),z,b))!=ESP_OK)return e;return b.generation==generation_?ESP_OK:ESP_ERR_INVALID_STATE;}
